if (open_list.empty()) {
    return nullptr;
}

auto lowest_it = open_list.begin();
float lowest_f = (*lowest_it)->g_value + (*lowest_it)->h_value;

for (auto it = open_list.begin() + 1; it != open_list.end(); ++it) {
    float current_f = (*it)->g_value + (*it)->h_value;
    if (current_f < lowest_f) {
        lowest_f = current_f;
        lowest_it = it;
    }
}

RouteModel::Node* lowest_node = *lowest_it;
open_list.erase(lowest_it);
return lowest_node;
